$ErrorActionPreference='Stop';
$cid='6ac45836-87a0-83ed-bea4-0ad0f99c8982';
function Conv([string]$u){try{$x=[uri]$u;$p=$x.AbsolutePath.Trim('/').Split('/');if($p.Length-eq2-and$p[0]-eq'c'){return $p[1]};if($p.Length-eq4-and$p[0]-eq'g'-and$p[2]-eq'c'){return $p[3]}}catch{};return ''}
$tabs=@(Invoke-RestMethod -Uri 'http://127.0.0.1:17410/json/list' -TimeoutSec 3);
$m=@($tabs|Where-Object{$_.type-eq'page'-and(Conv $_.url)-eq$cid});
if($m.Count -gt 1){ throw "duplicate exact Bridge conversation tabs: $($m.Count)" }
if($m.Count -eq 0){
  $url='https://chatgpt.com/c/'+$cid;
  Invoke-RestMethod -Method Put -Uri ('http://127.0.0.1:17410/json/new?'+[uri]::EscapeDataString($url)) -TimeoutSec 3|Out-Null;
  Start-Sleep -Milliseconds 1200;
}
$tabs=@(Invoke-RestMethod -Uri 'http://127.0.0.1:17410/json/list' -TimeoutSec 3);
$m=@($tabs|Where-Object{$_.type-eq'page'-and(Conv $_.url)-eq$cid});
[pscustomobject]@{count=$m.Count;tabs=@($m|Select-Object id,title,url,webSocketDebuggerUrl)}|ConvertTo-Json -Depth 4 -Compress
